function calculateGradeFromPercentage(percentage) {
  const num = Number(percentage);
  if (isNaN(num)) return { grade: "N/A", status: "Invalid", gpa: 0.0 };
  if (num >= 90) return { grade: "A+", status: "Passed with Distinction", gpa: 4.0 };
  if (num >= 80) return { grade: "A", status: "Passed First Division", gpa: 3.7 };
  if (num >= 70) return { grade: "B", status: "Passed Second Division", gpa: 3.0 };
  if (num >= 60) return { grade: "C", status: "Passed Third Division", gpa: 2.0 };
  return { grade: "F", status: "Needs Improvement", gpa: 0.0 };
}

module.exports = { PEDAGOGICAL_RUBRICS, calculateGradeFromPercentage };